import{_ as e,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"High Performance Erasure Coding - the Story so Far - Connor Fawcett, IBM","description":"","frontmatter":{"title":"High Performance Erasure Coding - the Story so Far - Connor Fawcett, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Erasure Coding","Performance Optimization","Storage Efficiency","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/High_Performance_Erasure_Coding_-_the_Story_so_Far_-_Connor_Fawcett_IBM.md","filePath":"posts/2025/High_Performance_Erasure_Coding_-_the_Story_so_Far_-_Connor_Fawcett_IBM.md","lastUpdated":1780459816000}'),i={name:"posts/2025/High_Performance_Erasure_Coding_-_the_Story_so_Far_-_Connor_Fawcett_IBM.md"};function l(n,r,s,u,_,g){return o(),t("div",null,[...r[0]||(r[0]=[a('<p>Ceph分布式存储系统中Erasure Coding（纠删码）的性能优化一直是存储领域的研究重点。以下是会议纪要的详细总结：</p><h3 id="会议纪要-ceph-erasure-coding-性能优化讨论" tabindex="-1">会议纪要：Ceph Erasure Coding 性能优化讨论 <a class="header-anchor" href="#会议纪要-ceph-erasure-coding-性能优化讨论" aria-label="Permalink to &quot;会议纪要：Ceph Erasure Coding 性能优化讨论&quot;">​</a></h3><p><strong>会议时间</strong>：未知<br><strong>主讲人</strong>：Connor Fawcett，IBM<br><strong>会议主题</strong>：Ceph中Erasure Coding性能优化</p><h4 id="_1-会议背景与动机" tabindex="-1">1. <strong>会议背景与动机</strong> <a class="header-anchor" href="#_1-会议背景与动机" aria-label="Permalink to &quot;1. **会议背景与动机**&quot;">​</a></h4><ul><li><strong>Erasure Coding的优势</strong>： <ul><li>相比于三副本复制（replication），Erasure Coding在降低总拥有成本（TCO）方面具有显著优势。</li><li>例如，4+2纠删码的存储开销仅是1.5倍，而三副本复制则是2倍。</li><li>尽管成本更低，但性能尚未达到足以让人们放弃复制的水平，因此大多数用户仍选择复制。</li></ul></li></ul><h4 id="_2-测试工具改进" tabindex="-1">2. <strong>测试工具改进</strong> <a class="header-anchor" href="#_2-测试工具改进" aria-label="Permalink to &quot;2. **测试工具改进**&quot;">​</a></h4><ul><li><strong>Offline Consistency Checker</strong>： <ul><li>这是一个Python工具，用于检查纠删码池中的数据一致性。</li><li>通过下线OSD，读取数据块和校验块，重新生成校验块并与存储的校验块进行比较，确保数据一致性。</li></ul></li><li><strong>IO Exerciser</strong>： <ul><li>现有的IO工具（如RBD bench）难以充分测试纠删码池的边界条件。</li><li>新工具生成更复杂的IO序列，支持多读多写操作，并可通过C++类与其他工具集成。</li></ul></li><li><strong>Online Consistency Checker</strong>： <ul><li>在线版本的工具，无需下线OSD，可实时检查数据一致性。</li><li>可以与IO Exerciser和其他工具集成，适用于需要频繁检查一致性的测试场景。</li></ul></li></ul><h4 id="_3-读写路径优化" tabindex="-1">3. <strong>读写路径优化</strong> <a class="header-anchor" href="#_3-读写路径优化" aria-label="Permalink to &quot;3. **读写路径优化**&quot;">​</a></h4><ul><li><strong>读路径优化</strong>： <ul><li><strong>当前问题</strong>：读取部分数据块时，需要读取整个数据条带（stripe），导致大量不必要的IO和网络放大。</li><li><strong>优化方案</strong>： <ul><li><strong>Partial Stripe Read</strong>：只读取所需的数据块，减少IO和网络放大。</li><li><strong>Minimum Required Read</strong>：只返回客户端请求的精确数据块，进一步减少开销。</li></ul></li></ul></li><li><strong>写路径优化</strong>： <ul><li><strong>当前问题</strong>：写操作时，需要先读取整个条带，合并新旧数据并重新生成校验块，导致大量不必要的IO。</li><li><strong>优化方案</strong>： <ul><li><strong>Minimum Required Write</strong>：只读取需要更新的数据块，合并新数据并生成校验块，然后只写回更新的数据块和校验块，减少IO开销。</li></ul></li></ul></li></ul><h4 id="_4-其他优化" tabindex="-1">4. <strong>其他优化</strong> <a class="header-anchor" href="#_4-其他优化" aria-label="Permalink to &quot;4. **其他优化**&quot;">​</a></h4><ul><li><strong>Buffer优化</strong>： <ul><li>通过引入两个缓冲区（payload buffer 和 raw data buffer），解决了对齐问题，显著减少了CPU开销。</li></ul></li><li><strong>元数据更新优化</strong>： <ul><li>在部分写操作中，元数据更新需要写入所有数据块，导致不必要的开销。</li><li>优化后，只更新实际写入的数据块的元数据，减少了元数据写入量。</li></ul></li></ul><h4 id="_5-性能测试结果" tabindex="-1">5. <strong>性能测试结果</strong> <a class="header-anchor" href="#_5-性能测试结果" aria-label="Permalink to &quot;5. **性能测试结果**&quot;">​</a></h4><ul><li><strong>测试对比</strong>： <ul><li>对比了当前版本（Squid）和优化后的原型分支在4K和8K随机读写操作中的性能。</li><li>结果显示，优化后的版本在IOPS和延迟方面有显著提升，尤其是在4K和8K的随机读写操作中。</li></ul></li></ul><h4 id="_6-后续计划" tabindex="-1">6. <strong>后续计划</strong> <a class="header-anchor" href="#_6-后续计划" aria-label="Permalink to &quot;6. **后续计划**&quot;">​</a></h4><ul><li>继续将优化合并到原型分支，并进行更多的性能测试，以进一步验证和展示优化效果。</li></ul><h4 id="_7-问答环节" tabindex="-1">7. <strong>问答环节</strong> <a class="header-anchor" href="#_7-问答环节" aria-label="Permalink to &quot;7. **问答环节**&quot;">​</a></h4><ul><li>主讲人回答了关于优化是否适用于所有纠删码算法的问题，表示大部分优化适用于常见的纠删码算法，但LRC（Locally Repairable Code）可能需要额外处理。</li></ul><p><strong>会议总结</strong>： 本次会议主要讨论了Ceph中Erasure Coding的性能优化，涵盖了测试工具的改进、读写路径的优化、缓冲区和元数据更新的优化，并通过性能测试展示了显著的性能提升。后续将继续推进这些优化的开发和测试工作。</p>',18)])])}const c=e(i,[["render",l]]);export{h as __pageData,c as default};
